import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.iWwp2X7T.js";const m=JSON.parse('{"title":"Capture model","description":"Mobile Inspector development documentation · Capture model","frontmatter":{"title":"Capture model","description":"Mobile Inspector development documentation · Capture model"},"headers":[],"relativePath":"en/guide/capture-model.md","filePath":"en/guide/capture-model.md"}'),n={name:"en/guide/capture-model.md"};function i(s,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="capture-model" tabindex="-1">Capture model <a class="header-anchor" href="#capture-model" aria-label="Permalink to &quot;Capture model&quot;">​</a></h1><p>Mobile Inspector observes the application&#39;s existing transport. It must not become a replacement transport, a second stream reader or a business retry controller.</p><h2 id="explicit-lifecycle" tabindex="-1">Explicit lifecycle <a class="header-anchor" href="#explicit-lifecycle" aria-label="Permalink to &quot;Explicit lifecycle&quot;">​</a></h2><p>Create the SDK stopped. Configure pairing while stopped, confirm the nonsecret destination, then start recording on a separate user action. Starting creates a new recording generation. Stop retains bounded local records but invalidates old handles and queued transfer. Clear stops recording, invalidates callbacks, purges memory and attempts the paired remote clear. Disconnect removes diagnostic delivery configuration.</p><p>On account/environment change, clear and disconnect before new work. Late callbacks from the old generation must not write into the new account. Closing a panel does not itself stop recording.</p><h2 id="read-once-observe-once" tabindex="-1">Read once, observe once <a class="header-anchor" href="#read-once-observe-once" aria-label="Permalink to &quot;Read once, observe once&quot;">​</a></h2><p>Adapters tee bytes as the business consumer reads them. SSE is parsed incrementally; incomplete tails are discarded. HTTP status, transport completion, cancellation and business success are different facts. Binary/file/audio payloads remain summaries. Native logs are explicit SDK calls; JavaScript can wrap console while preserving original output.</p><h2 id="bounded-evidence" tabindex="-1">Bounded evidence <a class="header-anchor" href="#bounded-evidence" aria-label="Permalink to &quot;Bounded evidence&quot;">​</a></h2><p>Defaults retain 100 requests, 20,000 events and 8 MiB serialized records. Per-request bodies are bounded to 1 MiB, SSE frames to 128 KiB. Batch/queue limits prevent unbounded background work. Explicit limit/gap markers mean a trace may be partial. Pairing never enables capture or diagnosis by itself.</p><p>Read <a href="./privacy">privacy</a> before enabling test bodies or exporting logs.</p>',10)])])}const b=a(n,[["render",i]]);export{m as __pageData,b as default};
